  "pattern_either": [
    "File.createTempFile($PREFIX, $SUFFIX)",
    "File.createTempFile($PREFIX, $SUFFIX, $DIR)"
  ],
  "pattern_not": [
    "createTempFile($PREFIX, $SUFFIX)",
    "Files.createTempFile(...)"
  ],
  "languages": [
    "java"
